solution:
import { useState } from 'react';

export function useScore(initial = 0) {
  const [score, setScore] = useState(initial);
  return {
    score,
    add: (amount) => setScore(s => s + amount),
    subtract: (amount) => setScore(s => Math.max(0, s - amount)),
    reset: () => setScore(initial),
  };
}
